    for off in range(L):
        have = Counter(); used = 0
        for i in range(off, len(s) - L + 1, L):
            if (i - off) // L >= m:
                old = s[i - m * L: i - (m - 1) * L]
                have[old] -= 1
                if have[old] < need[old]:
